import zlib

class BloomFilter:
    def __init__(self, m_bits, k):
        self.m, self.k = m_bits, k
        self.bits = bytearray((m_bits + 7) // 8)

    def _pos(self, key):
        b = key.encode("utf-8")
        return [zlib.crc32(b + bytes([i])) % self.m for i in range(self.k)]

    def add(self, key):
        for p in self._pos(key):
            self.bits[p // 8] |= (1 << (p % 8))

    def contains(self, key):
        return all(self.bits[p // 8] & (1 << (p % 8)) for p in self._pos(key))


class DB:
    def __init__(self):
        self.rows = {"id:%d" % i: "row-%d" % i for i in range(1, 101)}
        self.queries = 0

    def get(self, key):
        self.queries += 1
        return self.rows.get(key)


def run(mode, requests):
    db = DB()
    cache = {}
    nulls = set()
    bf = BloomFilter(m_bits=4096, k=4)
    for k in db.rows:
        bf.add(k)
    served = 0
    for key in requests:
        if mode == "none":
            v = cache.get(key)
            if v is None:
                v = db.get(key)
                if v is not None:
                    cache[key] = v
        elif mode == "bloom":
            if not bf.contains(key):
                served += 1
                continue
            v = cache.get(key)
            if v is None:
                v = db.get(key)
                if v is not None:
                    cache[key] = v
        elif mode == "nullcache":
            if key in nulls:
                served += 1
                continue
            v = cache.get(key)
            if v is None:
                v = db.get(key)
                if v is None:
                    nulls.add(key)
                else:
                    cache[key] = v
    return db.queries, served


# 1000 次请求，全部查询「根本不存在」的 id（穿透攻击）
requests = ["id:%d" % i for i in range(10000, 11000)]

for mode, name in [("none", "无防护"), ("bloom", "布隆过滤器"), ("nullcache", "缓存空值")]:
    q, blocked = run(mode, requests)
    print("%-12s: 请求 %d 次 -> DB 查询 %d 次, 被拦截 %d 次" % (name, len(requests), q, blocked))

q0, _ = run("none", requests)
q1, _ = run("bloom", requests)
q2, _ = run("nullcache", requests)
print("回源下降比例: 布隆 %.1f%%, 空值 %.1f%%" % (100.0 * (q0 - q1) / q0, 100.0 * (q0 - q2) / q0))
print("注意: 布隆无假阴性，判定不存在的请求一定不该放给 DB；空值缓存首次仍会回源一次")
